"""
Pydantic Models for Agent Outputs, Structured Metadata, and Human-in-the-Loop Interactions.
"""

from typing import List, Optional, Dict, Any, Tuple
from pydantic import BaseModel, Field
from deeplense_agent.models.parameters import (
    SimulationParameters,
    ModelConfiguration,
    SubstructureType,
)


class ClarificationQuestion(BaseModel):
    """A structured question generated by the agent during the HITL clarification step."""
    parameter_name: str = Field(..., description="Target parameter requiring clarification or refinement")
    current_or_default_value: Any = Field(..., description="Currently assumed or default value")
    suggested_options: List[str] = Field(default_factory=list, description="Recommended choices or ranges")
    question_text: str = Field(..., description="Conversational question explaining why clarification is needed")
    scientific_rationale: str = Field(..., description="Astrophysical context explaining this parameter's effect")


class SimulationPlan(BaseModel):
    """
    Simulation Plan generated after analyzing user prompt.
    Contains proposed parameters and indicates whether confirmation or clarifications are needed.
    """
    plan_id: str = Field(..., description="Unique identifier for the simulation plan")
    summary: str = Field(..., description="Human-readable executive summary of the requested simulation")
    parameters: SimulationParameters = Field(..., description="Validated simulation parameters")
    clarifications: List[ClarificationQuestion] = Field(
        default_factory=list,
        description="List of clarification questions if the user request was ambiguous or underspecified"
    )
    requires_user_confirmation: bool = Field(
        default=True,
        description="True if the plan is ready for user sign-off before running compute"
    )
    estimated_compute_time_sec: float = Field(
        default=0.5,
        description="Estimated execution time in seconds"
    )


class SingleImageMetadata(BaseModel):
    """Detailed astrophysical and numerical metadata for a single generated lensing image."""
    image_index: int = Field(..., description="Index in batch")
    model_configuration: ModelConfiguration = Field(..., description="Model configuration used")
    substructure_type: SubstructureType = Field(..., description="Dark matter substructure type")
    dimensions: Tuple[int, int] = Field(..., description="Pixel dimensions (height, width)")
    pixel_scale_arcsec: float = Field(..., description="Pixel scale in arcsec/pixel")
    z_lens: float = Field(..., description="Lens redshift")
    z_source: float = Field(..., description="Source redshift")
    einstein_radius_arcsec: float = Field(..., description="Calculated Einstein radius theta_E in arcsec")
    min_intensity: float = Field(..., description="Minimum pixel flux intensity")
    max_intensity: float = Field(..., description="Peak pixel flux intensity")
    mean_intensity: float = Field(..., description="Mean pixel flux intensity")
    estimated_snr: float = Field(..., description="Estimated signal-to-noise ratio")
    subhalo_count: int = Field(default=0, description="Number of substructure components injected")
    notes: List[str] = Field(default_factory=list, description="Astrophysical notes or warnings")


class SimulationExecutionOutput(BaseModel):
    """
    Structured output returned by the agent upon completing the simulation.
    Contains metadata, convergence info, and execution statistics.
    """
    plan_id: str = Field(..., description="Associated simulation plan ID")
    success: bool = Field(..., description="Whether simulation completed without error")
    num_images_generated: int = Field(..., description="Number of images generated")
    model_configuration: ModelConfiguration = Field(..., description="Configuration executed")
    substructure_type: SubstructureType = Field(..., description="Substructure type simulated")
    images_metadata: List[SingleImageMetadata] = Field(..., description="Per-image structured metadata")
    execution_time_seconds: float = Field(..., description="Elapsed wall-clock runtime")
    summary: str = Field(..., description="Summary of the simulated images and physical characteristics")
